from __future__ import annotations

import json
from html import escape
from typing import Any


def render_workbench(package_id: str, tasks: list[dict[str, Any]]) -> str:
    payload = json.dumps(tasks, ensure_ascii=False).replace("</", "<\\/")
    title = escape(f"Offline Mini Eval · {package_id}")
    return f'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{title}</title><style>
:root{{--bg:#f2f5f4;--panel:#fff;--ink:#172522;--muted:#65736f;--line:#dce5e2;--green:#087a61;--green2:#dff3ec;--nav:#102f29;--red:#b54338;--amber:#9a6810}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,"Segoe UI","Microsoft YaHei",sans-serif}}button,input,textarea,select{{font:inherit}}button{{cursor:pointer}}.top{{height:68px;background:var(--nav);color:white;display:flex;align-items:center;justify-content:space-between;padding:0 24px;position:sticky;top:0;z-index:5}}.top h1{{font-size:18px;margin:0}}.top p{{font-size:11px;color:#a9ccc1;margin:4px 0 0}}.badge{{background:#19473d;padding:8px 11px;border-radius:8px;font-size:12px}}.layout{{display:grid;grid-template-columns:300px minmax(0,1fr);min-height:calc(100vh - 68px)}}aside{{background:#e9efed;border-right:1px solid var(--line);padding:17px;position:sticky;top:68px;height:calc(100vh - 68px);overflow:auto}}main{{padding:22px;max-width:1280px;width:100%;margin:auto}}.panel{{background:var(--panel);border:1px solid var(--line);border-radius:13px;padding:18px;margin-bottom:14px;box-shadow:0 4px 14px #17342c0a}}h2{{font-size:17px;margin:0 0 13px}}h3{{font-size:14px;margin:0 0 8px}}label{{display:block;font-size:11px;color:var(--muted);font-weight:700;margin:10px 0 5px}}input,textarea,select{{width:100%;border:1px solid #cbd8d4;border-radius:8px;padding:10px;background:#fff}}textarea{{resize:vertical;min-height:170px;line-height:1.55}}.grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}}.grid2{{display:grid;grid-template-columns:1fr 1fr;gap:10px}}.tabs{{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin-bottom:13px}}.tab{{border:1px solid #c8d7d2;background:white;border-radius:7px;padding:9px 4px;font-size:11px}}.tab.active{{background:var(--green);color:white;border-color:var(--green)}}.progress{{height:8px;background:#d2dedb;border-radius:8px;overflow:hidden;margin:8px 0}}.progress i{{display:block;height:100%;background:var(--green);width:0}}.filters{{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin:12px 0}}.task{{display:block;width:100%;border:0;border-left:4px solid transparent;text-align:left;background:transparent;border-radius:6px;padding:9px;margin:3px 0;color:#34443f}}.task:hover{{background:#fff}}.task.active{{background:#fff;border-left-color:var(--green);font-weight:800}}.task.done::after{{content:'✓';float:right;color:var(--green)}}.task small{{display:block;color:var(--muted);font-weight:400;margin-top:3px}}.meta{{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:13px}}.pill{{font-size:11px;background:var(--green2);color:#176550;padding:5px 8px;border-radius:6px}}.prompt{{white-space:pre-wrap;background:#f6f8f7;border:1px solid var(--line);border-radius:9px;padding:15px;max-height:460px;overflow:auto;line-height:1.55;font-size:13px}}pre{{white-space:pre-wrap;word-break:break-word;background:#102521;color:#d9eee7;padding:13px;border-radius:8px;max-height:330px;overflow:auto;font-size:11px}}.actions{{display:flex;gap:8px;flex-wrap:wrap}}.primary{{border:0;background:var(--green);color:#fff;border-radius:8px;padding:10px 14px}}.secondary{{border:1px solid #bad0ca;background:white;color:var(--green);border-radius:8px;padding:9px 13px}}.danger{{border:1px solid #e2bcb8;background:#fff5f4;color:var(--red);border-radius:8px;padding:9px 13px}}.notice{{background:#fff8e7;border:1px solid #eedaa5;border-radius:8px;padding:11px;color:#6f5318;font-size:12px;line-height:1.5}}.status{{font-size:12px;margin-top:10px;color:var(--muted)}}.status.error{{color:var(--red)}}.raw-note{{font-size:11px;color:var(--muted);line-height:1.5}}.nav{{display:flex;justify-content:space-between;margin-top:12px}}details{{margin-top:10px}}@media(max-width:850px){{.layout{{grid-template-columns:1fr}}aside{{position:static;height:auto;max-height:400px}}.grid,.grid2{{grid-template-columns:1fr}}}}
</style></head><body>
<header class="top"><div><h1>Offline Mini Eval 人工执行台</h1><p>{escape(package_id)} · 无 API 调用 · 浏览器本地保存</p></div><span class="badge" id="top-progress">0 / {len(tasks)}</span></header>
<div class="layout"><aside>
<div class="tabs" id="model-tabs"></div>
<div><strong id="slot-title">模型1</strong><div class="progress"><i id="bar"></i></div><small id="progress-text">0 / {len(tasks)} 已完成</small></div>
<div class="filters"><select id="bench-filter"><option value="">全部任务</option><option>FinanceBench</option><option>BFCL v3</option></select><select id="state-filter"><option value="">全部状态</option><option value="todo">未完成</option><option value="done">已完成</option></select></div>
<div id="task-list"></div></aside><main>
<section class="panel"><h2>模型元数据</h2><div class="notice">每个 Slot 对应一个真实模型。请填写产品页面显示的精确模型名与版本；不要填写“GPT”“Claude”等泛称。所有内容只保存在当前浏览器，直到你导出 JSONL。</div><div class="grid"><div><label>Provider</label><input id="provider" placeholder="例如 OpenAI / Anthropic / Google"></div><div><label>Model Name</label><input id="model-name" placeholder="例如 Claude 3.7 Sonnet"></div><div><label>Exact Model Version</label><input id="model-version" placeholder="例如 claude-3-7-sonnet-20250219"></div></div><label>执行环境 / 备注</label><input id="model-notes" placeholder="例如官方Web界面；关闭联网；新会话逐题执行"></section>
<section class="panel"><div class="meta"><span class="pill" id="task-index"></span><span class="pill" id="benchmark"></span><span class="pill" id="task-id"></span></div><h2 id="idea-name"></h2><h3>请复制下面的完整 Prompt 到外部模型</h3><div class="prompt" id="prompt"></div><details id="tools-wrap"><summary>Tool Schema（BFCL必须一并提供）</summary><pre id="tools"></pre></details><div class="actions" style="margin-top:12px"><button class="primary" id="copy-prompt">复制完整 Prompt</button><button class="secondary" id="copy-tools">复制 Tool Schema</button><button class="secondary" id="start-timer">开始计时</button></div><p class="status" id="copy-status"></p></section>
<section class="panel"><h2>粘贴真实模型结果</h2><label>Verbatim Model Response</label><textarea id="response" placeholder="原样粘贴模型输出，不要人工改写。FinanceBench需保留答案与页码引用；BFCL需整理为约定的JSON数组。"></textarea><div class="grid2"><div><label>Started At</label><input id="started-at" type="datetime-local" step="1"></div><div><label>Completed At</label><input id="completed-at" type="datetime-local" step="1"></div></div><label>原始结果保存方式</label><select id="capture-mode"><option value="manual_external_ui">外部Web/客户端人工复制</option><option value="provider_export">Provider导出记录</option><option value="local_runtime_log">本地模型运行日志</option></select><label>Raw Response / 原始运行记录（可粘贴JSON；若无导出能力，系统会透明记录人工原样捕获）</label><textarea id="raw" style="min-height:110px" placeholder='优先粘贴Provider导出的完整JSON。没有时可留空，导出时会记录 capture_mode=manual_external_ui 和 verbatim_response。'></textarea><label>操作员备注</label><input id="notes" placeholder="异常、重试、模型拒答、格式整理说明等"><p class="raw-note">人工模式不会伪造 Provider Raw JSON。留空时会明确标记为 manual_external_ui，而不是声称这是 API 原始响应。</p><div class="actions"><button class="primary" id="save-next">保存并下一题</button><button class="secondary" id="save">仅保存</button><button class="danger" id="clear-task">清空本题</button></div><p class="status" id="save-status"></p><div class="nav"><button class="secondary" id="prev">← 上一题</button><button class="secondary" id="next">下一题 →</button></div></section>
<section class="panel"><h2>导出与交接</h2><div class="notice">每个模型完成20题后分别导出。最终把3个 `model-slot-*.jsonl` 放入同一文件夹，再使用包内 `combine_results.bat` 合并并校验。</div><div class="actions"><button class="primary" id="export-slot">导出当前模型 JSONL</button><button class="secondary" id="export-backup">导出工作台备份 JSON</button><label class="secondary" style="margin:0;cursor:pointer">导入工作台备份<input id="import-backup" type="file" accept="application/json" style="display:none"></label><button class="danger" id="reset-slot">重置当前模型</button></div><p class="status" id="export-status"></p></section>
</main></div><script>
const TASKS={payload}, PACKAGE_ID={json.dumps(package_id)}; let slot=0,current=0,timerStart=null;
const $=s=>document.querySelector(s); const key=s=>`${{PACKAGE_ID}}::slot-${{s}}`; const empty=()=>({{meta:{{provider:'',model_name:'',model_version:'',notes:''}},answers:{{}}}});
function loadSlot(s){{try{{return JSON.parse(localStorage.getItem(key(s)))||empty()}}catch{{return empty()}}}} function store(d){{localStorage.setItem(key(slot),JSON.stringify(d))}}
function isoLocal(value){{if(!value)return '';const d=new Date(value);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,19)}} function utc(value){{return value?new Date(value).toISOString():''}}
function download(name,text,type='application/json'){{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{{type}}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}} async function copyText(text){{if(navigator.clipboard&&window.isSecureContext){{await navigator.clipboard.writeText(text);return}}const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();document.execCommand('copy');area.remove()}}
function doneCount(d){{return TASKS.filter(t=>d.answers[t.task_id]?.response_text?.trim()).length}}
function saveMeta(){{const d=loadSlot(slot);d.meta={{provider:$('#provider').value.trim(),model_name:$('#model-name').value.trim(),model_version:$('#model-version').value.trim(),notes:$('#model-notes').value.trim()}};store(d)}}
function saveAnswer(show=true){{saveMeta();if($('#response').value.trim()&&!$('#completed-at').value)$('#completed-at').value=isoLocal(new Date().toISOString());const d=loadSlot(slot),t=TASKS[current],text=$('#response').value.trim(),raw=$('#raw').value.trim();let parsedRaw=null;if(raw){{try{{parsedRaw=JSON.parse(raw)}}catch{{parsedRaw={{capture_mode:$('#capture-mode').value,verbatim_raw_text:raw,parse_status:'not_json'}}}}}}else if(text){{parsedRaw={{capture_mode:'manual_external_ui',verbatim_response:text,provider_raw_unavailable:true}}}}d.answers[t.task_id]={{response_text:text,raw_response:parsedRaw,started_at:utc($('#started-at').value),completed_at:utc($('#completed-at').value),capture_mode:$('#capture-mode').value,operator_notes:$('#notes').value.trim()}};store(d);if(show){{$('#save-status').textContent=text?'已保存到浏览器本地':'已保存空记录';$('#save-status').className='status'}}renderSidebar()}}
function renderTabs(){{$('#model-tabs').innerHTML=[0,1,2].map(s=>`<button class="tab ${{s===slot?'active':''}}" data-slot="${{s}}">模型${{s+1}}</button>`).join('');document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{{saveAnswer(false);slot=+b.dataset.slot;current=0;render()}})}}
function renderSidebar(){{const d=loadSlot(slot),done=doneCount(d),bf=$('#bench-filter').value,sf=$('#state-filter').value;$('#slot-title').textContent=d.meta.model_name||`模型 Slot ${{slot+1}}`;$('#bar').style.width=`${{done/TASKS.length*100}}%`;$('#progress-text').textContent=`${{done}} / ${{TASKS.length}} 已完成`;$('#top-progress').textContent=`当前模型 ${{done}} / ${{TASKS.length}}`;$('#task-list').innerHTML=TASKS.map((t,i)=>({{t,i,done:!!d.answers[t.task_id]?.response_text?.trim()}})).filter(x=>(!bf||x.t.benchmark_name===bf)&&(!sf||(sf==='done')===x.done)).map(x=>`<button class="task ${{x.i===current?'active':''}} ${{x.done?'done':''}}" data-index="${{x.i}}">${{x.i+1}}. ${{x.t.benchmark_name}}<small>${{x.t.task_id.split('::').pop()}}</small></button>`).join('');document.querySelectorAll('.task').forEach(b=>b.onclick=()=>{{saveAnswer(false);current=+b.dataset.index;renderTask()}})}}
function renderTask(){{const d=loadSlot(slot),t=TASKS[current],a=d.answers[t.task_id]||{{}};$('#provider').value=d.meta.provider||'';$('#model-name').value=d.meta.model_name||'';$('#model-version').value=d.meta.model_version||'';$('#model-notes').value=d.meta.notes||'';$('#task-index').textContent=`Task ${{current+1}} / ${{TASKS.length}}`;$('#benchmark').textContent=t.benchmark_name;$('#task-id').textContent=t.task_id;$('#idea-name').textContent=t.idea_name;$('#prompt').textContent=t.messages.map(x=>`${{x.role.toUpperCase()}}\n${{x.content}}`).join('\n\n');$('#tools').textContent=JSON.stringify(t.tools,null,2);$('#tools-wrap').style.display=t.tools.length?'block':'none';$('#copy-tools').style.display=t.tools.length?'inline-block':'none';$('#response').value=a.response_text||'';$('#raw').value=a.raw_response&&a.raw_response.capture_mode!=='manual_external_ui'?JSON.stringify(a.raw_response,null,2):'';$('#started-at').value=isoLocal(a.started_at);$('#completed-at').value=isoLocal(a.completed_at);$('#capture-mode').value=a.capture_mode||'manual_external_ui';$('#notes').value=a.operator_notes||'';$('#save-status').textContent='';renderSidebar()}}
function render(){{renderTabs();renderTask()}}; ['provider','model-name','model-version','model-notes'].forEach(id=>$('#'+id).addEventListener('change',saveMeta));$('#bench-filter').onchange=renderSidebar;$('#state-filter').onchange=renderSidebar;
$('#copy-prompt').onclick=async()=>{{const t=TASKS[current];let text=t.messages.map(x=>x.content).join('\n\n');if(t.tools.length)text+=`\n\nTool Schema:\n${{JSON.stringify(t.tools,null,2)}}`;await copyText(text);if(!$('#started-at').value)$('#started-at').value=isoLocal(new Date().toISOString());$('#copy-status').textContent='完整Prompt已复制，并已记录开始时间';}};$('#copy-tools').onclick=async()=>{{await copyText(JSON.stringify(TASKS[current].tools,null,2));$('#copy-status').textContent='Tool Schema已复制';}};
$('#start-timer').onclick=()=>{{timerStart=new Date();$('#started-at').value=isoLocal(timerStart.toISOString());$('#start-timer').textContent='计时中…';}};$('#response').addEventListener('input',()=>{{if(timerStart&&!$('#completed-at').value)$('#completed-at').value=isoLocal(new Date().toISOString())}});$('#save').onclick=()=>saveAnswer();$('#save-next').onclick=()=>{{saveAnswer();if(current<TASKS.length-1)current++;renderTask()}};$('#prev').onclick=()=>{{saveAnswer(false);current=Math.max(0,current-1);renderTask()}};$('#next').onclick=()=>{{saveAnswer(false);current=Math.min(TASKS.length-1,current+1);renderTask()}};$('#clear-task').onclick=()=>{{if(confirm('清空当前题目的响应？')){{const d=loadSlot(slot);delete d.answers[TASKS[current].task_id];store(d);renderTask()}}}};
function slotRows(){{saveAnswer(false);const d=loadSlot(slot),m=d.meta,errors=[];if(!m.provider||!m.model_name||!m.model_version)errors.push('请完整填写 Provider、Model Name、Exact Model Version');const rows=[];TASKS.forEach(t=>{{const a=d.answers[t.task_id];if(!a?.response_text?.trim())errors.push(`未完成：${{t.task_id}}`);else{{rows.push({{package_id:PACKAGE_ID,task_id:t.task_id,model_name:m.model_name,model_version:m.model_version,provider:m.provider,started_at:a.started_at||a.completed_at,completed_at:a.completed_at||a.started_at,latency_seconds:a.started_at&&a.completed_at?Math.max(0,(new Date(a.completed_at)-new Date(a.started_at))/1000):null,response_text:a.response_text,raw_response:a.raw_response||{{capture_mode:'manual_external_ui',verbatim_response:a.response_text,provider_raw_unavailable:true}},request_metadata:{{temperature:0,capture_mode:a.capture_mode||'manual_external_ui',operator_notes:a.operator_notes||'',model_notes:m.notes||''}}}})}}}});return{{rows,errors}}}}
$('#export-slot').onclick=()=>{{const x=slotRows();if(x.errors.length){{$('#export-status').textContent=`不能导出：${{x.errors.slice(0,4).join('；')}}${{x.errors.length>4?'…':''}}`;$('#export-status').className='status error';return}}const model=loadSlot(slot).meta.model_name.replace(/[^a-zA-Z0-9._-]+/g,'-');download(`model-slot-${{slot+1}}-${{model}}.jsonl`,x.rows.map(r=>JSON.stringify(r)).join('\n')+'\n','application/x-ndjson');$('#export-status').textContent=`已导出 ${{x.rows.length}} 条真实响应`;$('#export-status').className='status'}};$('#export-backup').onclick=()=>download(`workbench-backup-slot-${{slot+1}}.json`,JSON.stringify(loadSlot(slot),null,2));$('#import-backup').onchange=async e=>{{const file=e.target.files[0];if(!file)return;const data=JSON.parse(await file.text());localStorage.setItem(key(slot),JSON.stringify(data));render()}};$('#reset-slot').onclick=()=>{{if(confirm('确认清空当前模型的全部20题数据？')){{localStorage.removeItem(key(slot));render()}}}};render();
</script></body></html>'''
